/// <summary>A parsed rhythmic feel occurrence: a catalog <see cref="RhythmicFeel"/> (or <see cref="RhythmicFeels.Generic"/>) plus the exact text it was
/// read from, tagged with how it entered the field. Its own type so a RhythmicFeelValue can't be used
/// where another dimension's value is expected (CLAUDE.md guideline 1).</summary>
public readonly record struct RhythmicFeelValue(RhythmicFeel Term, string StoredValue, ValueOrigin Origin = ValueOrigin.Stored)
{
    /// <summary>False when the value did not match the catalog (Term == RhythmicFeels.Generic).</summary>
    public bool IsKnown => !ReferenceEquals(Term, RhythmicFeels.Generic);
    /// <summary>The catalog form; equals StoredValue for an unknown (Generic has no canonical).</summary>
    public string Canonical => IsKnown ? Term.Canonical : StoredValue;
}

/// <summary>A rhythmic feel field reading: the parsed values plus the exact original frame string
/// (preserved for byte-for-byte write-back).</summary>
public sealed record RhythmicFeelField(IReadOnlyList<RhythmicFeelValue> Values, string RawFrame);

