    private readonly string _delimiter;

    /// <summary>Wrap a runtime dimension; <paramref name="delimiter"/> is the multi-value separator.</summary>
    public RhythmicFeelView(Dimension dimension, string delimiter = "; ")
    {
        _dim = dimension;
        _delimiter = string.IsNullOrEmpty(delimiter) ? "; " : delimiter;
    }

    /// <summary>The generic (not-in-catalog) rhythmic feel term.</summary>
    public RhythmicFeel Generic => RhythmicFeels.Generic;

    /// <summary>Resolve one token; a miss returns the generic carrying the raw text. Never null.</summary>
    public RhythmicFeelValue Resolve(string token)
    {
        var term = _dim.Resolve(token);
        if (term is null) return new RhythmicFeelValue(RhythmicFeels.Generic, token);
        var hit = RhythmicFeels.ById.TryGetValue(term.Id, out var c) ? c : RhythmicFeels.FromTerm(term);
        return new RhythmicFeelValue(hit, token);
    }

    /// <summary>Read a whole (multi-value) frame: per-value occurrences + the exact original frame.</summary>
    public RhythmicFeelField Read(string? rawFrame)
    {
        var frame = rawFrame ?? "";
        var values = new List<RhythmicFeelValue>();
        foreach (var part in frame.Split([_delimiter], System.StringSplitOptions.None))
        {
            var token = part.Trim();
            if (token.Length == 0) continue;
            values.Add(Resolve(token));
        }
        return new RhythmicFeelField(values, frame);
    }
}

